# Secure agent registration
APPROVED_HOSTS = {"payroll.nexora.local", "customer.nexora.local"}

@app.post("/agents/register")
def register(card_url: str, token: str):
    require_valid_token(token)                 # 1. authentication
    card = fetch_card(card_url)
    if not verify_signature(card):             # 2. signed cards only
        abort(403, "Unsigned or tampered card")
    host = urlparse(card["url"]).hostname
    if host not in APPROVED_HOSTS:             # 3. allow-list
        abort(403, "Host not approved")
    registry.add(card)
    return {"status": "registered"}

# Workflow steps are enforced, not optional
def run_workflow(prompt):
    data = data_agent.run(prompt)
    deck = presentation_agent.run(data)

    # SECURITY SCAN IS MANDATORY - no prompt can skip this
    report = security_agent.scan(deck)
    if report.risk_level == "HIGH":
        raise SecurityError("Blocked: unsafe content detected")

    return deliver(deck, report)
